    // Credentials embedded in a URL: scheme://user:pass@host -> scheme://[redacted]@host
    out = out.replace(/(\b[a-z][a-z0-9+.-]*:\/\/)[^/\s:@]+:[^/\s@]+@/gi, `$1${R}@`);
