    out = out.replace(new RegExp(`(${key}\\s*=\\s*)${dq}`, "gi"), `$1"${R}"`);
    out = out.replace(new RegExp(`(${key}\\s*=\\s*)${sq}`, "gi"), `$1'${R}'`);
    out = out.replace(new RegExp(`(${key}\\s*=\\s*)[^\\s"',;}]+`, "gi"), `$1${R}`);
