    // ':' is a reference/name — a Kubernetes Secret NAME (secret: partner-gateway-tls)
    // is content, not a credential, so it is left intact (Grok's over-redaction case).
    out = out.replace(new RegExp(`(${key}\\s*:\\s*)${dq}`, "gi"), `$1"${R}"`);
